    String includingOffsetStr = includingOffset ? "inclusive" : "exclusive";
    maybeHandleIOException(
            () -> "Error while flushing log for " + topicPartition() + " in dir " + dir().getParent() + " with offset " + offset +
            " (" + includingOffsetStr + ") and recovery point " + offset,
            () -> {
                if (flushOffset > localLog.recoveryPoint()) {
                    logger.debug("Flushing log up to offset {} ({}) with recovery point {}, last flushed: {},  current time: {}, unflushed: {}",
                            offset, includingOffsetStr, offset, lastFlushTime(), time().milliseconds(), localLog.unflushedMessages());
                    localLog.flush(flushOffset);
                    synchronized (lock) {
                        localLog.markFlushed(offset);
                    }
                }
                return null;
            });
}

def handleProduceRequest(request: Request, requestLocal: RequestLocal): Unit = {
  val produceRequest = request.body(classOf[ProduceRequest])

  if (RequestUtils.hasTransactionalRecords(produceRequest)) {
    val isAuthorizedTransactional = produceRequest.transactionalId != null &&
      authHelper.authorize(request.context, WRITE, TRANSACTIONAL_ID, produceRequest.transactionalId)
    if (!isAuthorizedTransactional) {
      requestHelper.sendErrorResponseMaybeThrottle(request, Errors.TRANSACTIONAL_ID_AUTHORIZATION_FAILED.exception)
      return
    }
  }

  val unauthorizedTopicResponses = mutable.Map[TopicIdPartition, PartitionResponse]()
  val nonExistingTopicResponses = mutable.Map[TopicIdPartition, PartitionResponse]()
  val invalidRequestResponses = mutable.Map[TopicIdPartition, PartitionResponse]()
  val authorizedRequestInfo = mutable.Map[TopicIdPartition, MemoryRecords]()
  val topicIdToPartitionData = new mutable.ArrayBuffer[(TopicIdPartition, ProduceRequestData.PartitionProduceData)]

  produceRequest.data.topicData.forEach { topic =>

// currently fenced. This is useful when handling unfencing. The reason is that
// while we're generating the records to handle unfencing, the ClusterControlManager
// still shows the node as fenced.
//
// Similarly, if the caller passed a valid broker ID for brokerToRemove, rather
// than passing NO_LEADER, that node will never be considered an acceptable leader.
// This is useful when handling a newly fenced node. We also exclude brokerToRemove
// from the target ISR, but we need to exclude it here too, to handle the case
// where there is an unclean leader election which chooses a leader from outside
// the ISR.
//
// If the caller passed a valid broker ID for brokerWithUncleanShutdown, rather than
// passing NO_LEADER, this node should not be an acceptable leader. We also exclude
// brokerWithUncleanShutdown from ELR and ISR.
IntPredicate isAcceptableLeader =
    r -> (r != brokerToRemove && r != brokerWithUncleanShutdown)
        && (r == brokerToAdd || clusterControl.isActive(r));

while (iterator.hasNext()) {
    TopicIdPartition topicIdPart = iterator.next();
    TopicControlInfo topic = topics.get(topicIdPart.topicId());
    if (topic == null) {
        throw new RuntimeException("Topic ID " + topicIdPart.topicId() +
            " existed in isrMembers, but not in the topics map.");
    }
    PartitionRegistration partition = topic.parts.get(topicIdPart.partitionId());
    if (partition == null) {
        throw new RuntimeException("Partition " + topicIdPart +
            " existed in isrMembers, but not in the partitions map.");
    }
    PartitionChangeBuilder builder = new PartitionChangeBuilder(
        partition,
        topicIdPart.topicId(),
        topicIdPart.partitionId(),
        new LeaderAcceptor(clusterControl, partition, isAcceptableLeader),
        featureControl.metadataVersionOrThrow(),
        getTopicEffectiveMinIsr(topic.name),
        featureControl.isElrFeatureEnabled()
    );
    if (configurationControl.uncleanLeaderElectionEnabledForTopic(topic.name)) {
        builder.setElection(PartitionChangeBuilder.Election.UNCLEAN);
    }
    if (brokerWithUncleanShutdown != NO_LEADER) {
        builder.setUncleanShutdownReplicas(List.of(brokerWithUncleanShutdown));
    }

    // Note: if brokerToRemove and brokerWithUncleanShutdown were passed as NO_LEADER, this is a no-op (the new
    // target ISR will be the same as the old one).
    builder.setTargetIsr(Replicas.toList(
        Replicas.copyWithout(partition.isr, new int[] {brokerToRemove, brokerWithUncleanShutdown})));

 * When the leader is elected or re-elected, the state of the follower is reinitialized
 * accordingly.
 */
public void resetReplicaState(
    long currentTimeMs,
    long leaderEndOffset,
    boolean isNewLeader,
    boolean isFollowerInSync
) {
    replicaState.updateAndGet(currentReplicaState -> {
        // When the leader is elected or re-elected, the follower's last caught up time
        // is set to the current time if the follower is in the ISR, else to 0. The latter
        // is done to ensure that the high watermark is not hold back unnecessarily for
        // a follower which is not in the ISR anymore.
        long lastCaughtUpTimeMs = isFollowerInSync ? currentTimeMs : 0L;

        if (isNewLeader) {
            return new ReplicaState(
                UnifiedLog.UNKNOWN_OFFSET,
                LogOffsetMetadata.UNKNOWN_OFFSET_METADATA,
                UnifiedLog.UNKNOWN_OFFSET,
                0L,
                lastCaughtUpTimeMs,
                Optional.empty()
            );
        } else {
            return new ReplicaState(
                currentReplicaState.logStartOffset(),
                currentReplicaState.logEndOffsetMetadata(),
                leaderEndOffset,
                // When the leader is re-elected, the follower's last fetch time is
                // set to the current time if the follower is in the ISR, else to 0.
                // The latter is done to ensure that the follower is not brought back
                // into the ISR before a fetch is received.
                isFollowerInSync ? currentTimeMs : 0L,
                lastCaughtUpTimeMs,
                currentReplicaState.brokerEpoch()
            );
        }
    });
